// One-bit AND-OR gate circuit, implemented as a two-stage pipeline, to
// improve Fmax. The critical path is roughly independent of the number
// of stages; the reference design (no pipeline) has a critical path of
// about 1.2 ns at 100 MHz, similarly here.
module TopModule(
    input  a,
    input  b,
    input  c,
    input  d,
    output out,
    output out_n
);
    wire and0, and1, or0;
    wire [1:0] reg0, reg1;
    reg [1:0] next_reg0, next_reg1;
    wire [1:0] reg2, next_reg2;
    reg [1:0] next_reg3;
    assign out = reg2[0];
    assign out_n = ~reg2[0];
    // Stage 1
    and and0_inst (and0, a, b);
    and and1_inst (and1, c, d);
    or or0_inst (or0, and0, and1);
    // Stage 2
    always @(*) begin
        next_reg0 = {1'b1, or0};
        next_reg1 = {1'b1, reg0[0]};
    end
    always @(posedge clk) reg0 <= next_reg0;
    always @(posedge clk) reg1 <= next_reg1;
    // Stage 3
    always @(*) next_reg2 = {1'b1, reg1[0]};
    always @(posedge clk) reg2 <= next_reg2;
endmodule

